### Recommended Approach (Node.js)

Since this environment has **Node.js v24**, you'd use two libraries:

| Task | Library |
|---|---|
| Extract PDF text | [`pdf-parse`](https://www.npmjs.com/package/pdf-parse) or [`pdfjs-dist`](https://www.npmjs.com/package/pdfjs-dist) |
| Write Excel file | [`exceljs`](https://www.npmjs.com/package/exceljs) or [`xlsx`](https://www.npmjs.com/package/xlsx) |

Here's a ready-to-use script. Want me to create it? Just tell me:

1. **Where is your PDF?** (path to the file, e.g. `/workspace/data/report.pdf`)
2. **Where should the Excel file go?** (e.g. `/workspace/data/output.xlsx`)

In the meantime, here's what the script would look like:

```js
// extract_pdf_to_excel.js
const pdf = require("pdf-parse");
const ExcelJS = require("exceljs");
const fs = require("fs");

async function main() {
  const pdfPath = process.argv[2];   // e.g. ./data/report.pdf
  const xlsxPath = process.argv[3];  // e.g. ./data/output.xlsx

  // 1. Read PDF & extract text from page 1 only
  const buffer = fs.readFileSync(pdfPath);
  const data = await pdf(buffer, {
    max: 1,  // only first page
  });

  // 2. Write text to Excel
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1 Text");
  sheet.columns = [{ header: "Line", key: "line", width: 120 }];

  data.text.split("\n").forEach((line) => {
    sheet.addRow({ line });
  });

  await workbook.xlsx.writeFile(xlsxPath);
  console.log(`✅ Saved to ${xlsxPath}`);
}

main().catch(console.error);
```

**Usage:**
```bash
npm install pdf-parse exceljs
node extract_pdf_to_excel.js ./data/report.pdf ./data/output.xlsx
```

