const pdfjsLib = require("pdfjs-dist/legacy/build/pdf.mjs");
const ExcelJS = require("exceljs");
const path = require("path");

const PDF_PATH = "/workspace/data/sample.pdf";
const XLSX_PATH = "/workspace/data/pdf_text_output.xlsx";

async function extractFirstPageText(pdfPath) {
  const doc = await pdfjsLib.getDocument(pdfPath).promise;
  console.log(`Total pages in PDF: ${doc.numPages}`);

  const page = await doc.getPage(1); // page 1
  const content = await page.getTextContent();

  // Join text items, preserving line breaks where the Y position changes
  let prevY = null;
  let text = "";
  for (const item of content.items) {
    if (item.str === undefined) continue;
    if (prevY !== null && Math.abs(item.transform[5] - prevY) > 2) {
      text += "\n";
    }
    text += item.str;
    prevY = item.transform[5];
  }
  return text;
}

async function main() {
  // 1. Extract text
  const text = await extractFirstPageText(PDF_PATH);
  const lines = text.split("\n").filter((l) => l.trim().length > 0);

  console.log(`Lines extracted from page 1: ${lines.length}\n`);

  // 2. Write to Excel
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1 Text");

